describe('applyPluginProperties', () => {
  const mockPlugin = {
    fullName: 'test-plugin',
    properties: jest.fn()
  }

  const mockPlugins = {
    getAll: jest.fn()
  }

  const mockError = {
    plugin: {}
  }

  let originalGetErrorPluginInfo, originalIsPlainObj, originalAssignError

  beforeEach(() => {
    jest.clearAllMocks()

    // Store original functions
    originalGetErrorPluginInfo = main.getErrorPluginInfo
    originalIsPlainObj = main.isPlainObj
    originalAssignError = main.assignError
  })

  afterEach(() => {
    // Restore original functions
    if (originalGetErrorPluginInfo) main.getErrorPluginInfo = originalGetErrorPluginInfo
    if (originalIsPlainObj) main.isPlainObj = originalIsPlainObj
    if (originalAssignError) main.assignError = originalAssignError
  })

  test('should return early when properties is undefined', () => {
    const pluginWithoutProperties = {
      ...mockPlugin,
      properties: undefined
    }

    const result = main.applyPluginProperties({
      error: mockError,
      plugin: pluginWithoutProperties,
      plugins: mockPlugins
    })

    expect(result).toBeUndefined()
    expect(mockPlugin.properties).not.toHaveBeenCalled()
  })

  test('should call getErrorPluginInfo and properties with correct arguments', () => {
    const mockInfo = { some: 'info' }
    const mockPropertiesResult = { prop1: 'value1' }

    // Mock the functions
    main.getErrorPluginInfo = jest.fn().mockReturnValue(mockInfo)
    main.isPlainObj = jest.fn().mockReturnValue(true)
    main.assignError = jest.fn()

    mockPlugin.properties.mockReturnValue(mockPropertiesResult)

    main.applyPluginProperties({
      error: mockError,
      plugin: mockPlugin,
      plugins: mockPlugins
    })

    expect(main.getErrorPluginInfo).toHaveBeenCalledWith({
      error: mockError,
      plugins: mockPlugins,
      plugin: mockPlugin
    })
    expect(mockPlugin.properties).toHaveBeenCalledWith(mockInfo)
  })

  test('should throw TypeError when properties returns non-plain object', () => {
    main.getErrorPluginInfo = jest.fn().mockReturnValue({})
    main.isPlainObj = jest.fn().mockReturnValue(false)

    mockPlugin.properties.mockReturnValue('not an object')

    expect(() => {
      main.applyPluginProperties({
        error: mockError,
        plugin: mockPlugin,
        plugins: mockPlugins
      })
    }).toThrow(
      new TypeError(
        `Plugin "${mockPlugin.fullName}"'s "properties()" must return a plain object: not an object`
      )
    )
  })

  test('should call assignError with correct arguments when properties returns valid object', () => {
    const mockNewProps = { prop1: 'value1', prop2: 'value2' }

    main.getErrorPluginInfo = jest.fn().mockReturnValue({})
    main.isPlainObj = jest.fn().mockReturnValue(true)
    main.assignError = jest.fn()

    mockPlugin.properties.mockReturnValue(mockNewProps)

    main.applyPluginProperties({
      error: mockError,
      plugin: mockPlugin,
      plugins: mockPlugins
    })

    expect(main.assignError).toHaveBeenCalledWith(mockError, mockNewProps, mockPlugins)
  })

  test('should handle null properties return value correctly', () => {
    main.getErrorPluginInfo = jest.fn().mockReturnValue({})
    main.isPlainObj = jest.fn().mockReturnValue(false)

