const prefixCause = (cause) => {
  const oldMessage = typeof cause.message === 'string' ? cause.message : ''
  const newMessage =
    oldMessage === '' ? cause.name : `${cause.name}: ${oldMessage}`
  setErrorMessage(cause, newMessage)
  return oldMessage
}

