// Create mock function first
const mockNormalizeMethods = jest.fn();

// Mock the module with proper hoisting
jest.mock('../../../../src/plugins/shape/methods.js', () => {
  const actualModule = jest.requireActual('../../../../src/plugins/shape/methods.js');

  // Create a new function that uses our mock
  const wrappedNormalizeAllMethods = (plugin) => {
    // Save original normalizeMethods
    const originalNormalizeMethods = actualModule.normalizeMethods;

    // Temporarily replace with mock
    actualModule.normalizeMethods = mockNormalizeMethods;

    try {
      // Call the actual function which will now use our mock
      return actualModule.normalizeAllMethods(plugin);
    } finally {
      // Restore original
      actualModule.normalizeMethods = originalNormalizeMethods;
    }
  };

  return {
    ...actualModule,
    normalizeAllMethods: wrappedNormalizeAllMethods,
    normalizeMethods: mockNormalizeMethods,
  };
});

// Import constants from actual module
const actualModule = jest.requireActual('../../../../src/plugins/shape/methods.js');
const { INSTANCE_METHODS, STATIC_METHODS } = actualModule;

describe('normalizeAllMethods', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should call normalizeMethods three times with correct arguments', () => {
    const mockPlugin = { name: 'testPlugin' };
    const mockPluginA = { name: 'pluginA' };
    const mockPluginB = { name: 'pluginB' };
    const mockPluginC = { name: 'pluginC' };

    mockNormalizeMethods
      .mockReturnValueOnce(mockPluginA)
      .mockReturnValueOnce(mockPluginB)
      .mockReturnValueOnce(mockPluginC);

    const result = normalizeAllMethods(mockPlugin);

    expect(mockNormalizeMethods).toHaveBeenCalledTimes(3);

    expect(mockNormalizeMethods).toHaveBeenNthCalledWith(1, {
      ...INSTANCE_METHODS,
      plugin: mockPlugin,
      propName: 'instanceMethods'
    });

    expect(mockNormalizeMethods).toHaveBeenNthCalledWith(2, {
      ...STATIC_METHODS,
      plugin: mockPluginA,
      propName: 'instanceMethods'
    });

    expect(mockNormalizeMethods).toHaveBeenNthCalledWith(3, {
      ...STATIC_METHODS,
      plugin: mockPluginB,
      propName: 'staticMethods'
    });

    expect(result).toBe(mockPluginC);
  });

  it('should handle empty plugin object', () => {
    const mockPlugin = {};
    const mockPluginA = { processed: true };
    const mockPluginB = { processed: true };
    const mockPluginC = { final: true };

    mockNormalizeMethods
      .mockReturnValueOnce(mockPluginA)
      .mockReturnValueOnce(mockPluginB)
      .mockReturnValueOnce(mockPluginC);

    const result = normalizeAllMethods(mockPlugin);

    expect(mockNormalizeMethods).toHaveBeenCalledTimes(3);
    expect(result).toBe(mockPluginC);
  });

  it('should preserve INSTANCE_METHODS and STATIC_METHODS constants', () => {
    const mockPlugin = { data: 'test' };

    mockNormalizeMethods.mockImplementation((args) => args);

    const result = normalizeAllMethods(mockPlugin);

    expect(mockNormalizeMethods).toHaveBeenNthCalledWith(1, 
      expect.objectContaining({
        ...INSTANCE_METHODS,
        plugin: mockPlugin,
        propName: 'instanceMethods'
      })
    );

    expect(mockNormalizeMethods).toHaveBeenNthCalledWith(2,
      expect.objectContaining({
        ...STATIC_METHODS,
        propName: 'instanceMethods'
      })
    );

    expect(mockNormalizeMethods).toHaveBeenNthCalledWith(3,
      expect.objectContaining({
        ...STATIC_METHODS,
        propName: 'staticMethods'
      })
    );
  });

  it('should pass plugin through the transformation chain', () => {
    const originalPlugin = { id: 1, config: { enabled: true } };
    const pluginA = { ...originalPlugin, stage1: 'processed' };
    const pluginB = { ...pluginA, stage2: 'processed' };
    const pluginC = { ...pluginB, stage3: 'processed' };

    mockNormalizeMethods
      .mockReturnValueOnce(pluginA)
      .mockReturnValueOnce(pluginB)
      .mockReturnValueOnce(pluginC);

    const result = normalizeAllMethods(originalPlugin);

    expect(mockNormalizeMethods.mock.calls[0][0].plugin).toBe(originalPlugin);
    expect(mockNormalizeMethods.mock.calls[1][0].plugin).toBe(pluginA);
    expect(mockNormalizeMethods.mock.calls[2][0].plugin).toBe(pluginB);
    expect(result).toBe(pluginC);
  });
});

