const deepCloneObject = require('../../../src/options/clone.js').deepCloneObject;

// Mock the deepClone dependency
jest.mock('../../../src/options/clone.js', () => {
  const originalModule = jest.requireActual('../../../src/options/clone.js');

  // Create a mock deepClone function that tracks calls
  let mockDeepClone = jest.fn(value => {
    // Simple cloning logic for mocking
    if (value === null || typeof value !== 'object') {
      return value;
    }
    if (Array.isArray(value)) {
      return [...value];
    }
    if (Object.getPrototypeOf(value) === null) {
      const nullProtoObj = Object.create(null);
      Object.assign(nullProtoObj, value);
      return nullProtoObj;
    }
    return { ...value };
  });

  return {
    ...originalModule,
    // Override deepClone reference in the module
    __deepClone: mockDeepClone,
    get deepCloneObject() {
      // Create a fresh closure that references our mock
      return (object) => {
        const copy = Object.create(Object.getPrototypeOf(object));
        for (const key of Reflect.ownKeys(object)) {
          const descriptor = Object.getOwnPropertyDescriptor(object, key);
          const childCopy = mockDeepClone(descriptor.value);

          // Handle accessor descriptors (getters/setters) differently
          if (descriptor.get || descriptor.set) {
            Object.defineProperty(copy, key, {
              get: descriptor.get,
              set: descriptor.set,
              enumerable: descriptor.enumerable,
              configurable: descriptor.configurable
            });
          } else {
            Object.defineProperty(copy, key, { ...descriptor, value: childCopy });
          }
        }
        return copy;
      };
    }
  };
});

describe('deepCloneObject', () => {
  beforeEach(() => {
    // Clear mock calls before each test
    jest.clearAllMocks();
  });

  test('should clone a simple object with own properties', () => {
    const original = {
      name: 'John',
      age: 30,
      city: 'New York'
    };

    const cloned = deepCloneObject(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned.name).toBe(original.name);
    expect(cloned.age).toBe(original.age);
    expect(cloned.city).toBe(original.city);
  });

  test('should clone object with getters and setters', () => {
    const original = {};
    let privateValue = 'secret';

    Object.defineProperties(original, {
      value: {
        get() { return privateValue; },
        set(newValue) { privateValue = newValue; },
        enumerable: true
      },
      readOnly: {
        get() { return 'constant'; },
        enumerable: true
      }
    });

    const cloned = deepCloneObject(original);

    expect(cloned.value).toBe('secret');
    expect(cloned.readOnly).toBe('constant');
  });

  test('should clone object with symbol keys', () => {
    const symbolKey = Symbol('unique');
    const original = {
      regular: 'value',
      [symbolKey]: 'symbol value'
    };

    const cloned = deepCloneObject(original);

    expect(cloned.regular).toBe('value');
    expect(cloned[symbolKey]).toBe('symbol value');
    expect(Reflect.ownKeys(cloned)).toEqual(Reflect.ownKeys(original));
  });

  test('should clone object with non-enumerable properties', () => {
    const original = { visible: 'visible' };

    Object.defineProperty(original, 'hidden', {
      value: 'hidden value',
      enumerable: false,
      writable: true,
      configurable: true
    });

    const cloned = deepCloneObject(original);

    expect(cloned.visible).toBe('visible');
    const clonedDescriptor = Object.getOwnPropertyDescriptor(cloned, 'hidden');
    expect(clonedDescriptor.value).toBe('hidden value');
    expect(clonedDescriptor.enumerable).toBe(false);
    expect(clonedDescriptor.writable).toBe(true);
    expect(clonedDescriptor.configurable).toBe(true);
  });

  test('should clone object with configurable and writable attributes preserved', () => {
    const original = {};

    Object.defineProperties(original, {
      writableProp: {
        value: 'can change',
        writable: true,
        enumerable: true,
        configurable: true
      },
      nonWritableProp: {
        value: 'cannot change',
        writable: false,
        enumerable: true,
        configurable: true
      },
      nonConfigurableProp: {
        value: 'cannot delete',
        writable: true,
        enumerable: true,
        configurable: false
      }
    });

    const cloned = deepCloneObject(original);

    // Test writable property
    cloned.writableProp = 'changed';
    expect(cloned.writableProp).toBe('changed');

    // Test non-writable property
    expect(() => {
      'use strict';
      cloned.nonWritableProp = 'trying to change';
    }).toThrow();
    expect(cloned.nonWritableProp).toBe('cannot change');

    // Test non-configurable property
    expect(() => {
      'use strict';
      delete cloned.nonConfigurableProp;
    }).toThrow();
    expect(cloned.nonConfigurableProp).toBe('cannot delete');
  });

  test('should handle empty object', () => {
    const original = {};
    const cloned = deepCloneObject(original);

    expect(cloned).toEqual({});
    expect(cloned).not.toBe(original);
    expect(Reflect.ownKeys(cloned)).toHaveLength(0);
  });

  test('should deeply clone nested objects by calling deepClone', () => {
    const original = {
      nested: {
        level1: {
          level2: 'deep value'
        }
      },
      array: [1, 2, 3]
    };

    const cloned = deepCloneObject(original);

    expect(cloned.nested).not.toBe(original.nested);
    expect(cloned.array).not.toBe(original.array);
    expect(cloned.nested.level1.level2).toBe(original.nested.level1.level2);
    expect(cloned.array).toEqual(original.array);
  });

  test('should preserve property descriptors exactly', () => {
    const original = {};

    const descriptor = {
      value: 'test value',
      writable: false,
      enumerable: true,
      configurable: true
    };

    Object.defineProperty(original, 'testProp', descriptor);

    const cloned = deepCloneObject(original);
    const clonedDescriptor = Object.getOwnPropertyDescriptor(cloned, 'testProp');

    expect(clonedDescriptor).toEqual(descriptor);
  });

  test('should handle object with null prototype', () => {
    const original = Object.create(null);
    original.a = 1;
    original.b = 2;

    const cloned = deepCloneObject(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(Object.getPrototypeOf(cloned)).toBe(null);
    expect(cloned.a).toBe(1);
    expect(cloned.b).toBe(2);
  });

  test('should clone object with function values', () => {
    const original = {
      method: function() { return 'result'; },
      arrow: () => 'arrow result'
    };

    const cloned = deepCloneObject(original);

    expect(typeof cloned.method).toBe('function');
    expect(typeof cloned.arrow).toBe('function');
    expect(cloned.method()).toBe('result');
    expect(cloned.arrow()).toBe('arrow result');
  });
});

