import { OMITTED_PROPS, getPluginsMethodNames } from '../../../../src/plugins/properties/assign.js'

jest.mock('../../../../src/plugins/properties/assign.js', () => {
  const originalModule = jest.requireActual('../../../../src/plugins/properties/assign.js')

  return {
    __esModule: true,
    ...originalModule,
    setErrorStack: jest.fn(),
    setErrorMessage: jest.fn(),
    setErrorProps: jest.fn(),
    excludeKeys: jest.fn(obj => Object.keys(obj)),
    OMITTED_PROPS: ['__proto__', 'constructor', 'prototype'],
    getPluginsMethodNames: jest.fn(() => [])
  }
})

describe('assignError', () => {
  let error
  let plugins

  beforeEach(() => {
    error = new Error('Original error')
    plugins = [{ method1: () => {}, method2: () => {} }]
    jest.clearAllMocks()
    getPluginsMethodNames.mockReturnValue(['method1', 'method2'])
  })

  afterEach(() => {
    jest.resetAllMocks()
  })

  it('should set stack when stack is provided', () => {
    const newProps = { stack: 'Custom stack trace' }

    assignError(error, newProps, plugins)

    expect(setErrorStack).toHaveBeenCalledWith(error, 'Custom stack trace')
    expect(setErrorMessage).not.toHaveBeenCalled()
    expect(setErrorProps).not.toHaveBeenCalled()
  })

  it('should set message when message is provided', () => {
    const newProps = { message: 'Custom error message' }

    assignError(error, newProps, plugins)

    expect(setErrorMessage).toHaveBeenCalledWith(error, 'Custom error message')
    expect(setErrorStack).not.toHaveBeenCalled()
    expect(setErrorProps).not.toHaveBeenCalled()
  })

  it('should set both stack and message when both are provided', () => {
    const newProps = { 
      stack: 'Custom stack trace',
      message: 'Custom error message'
    }

    assignError(error, newProps, plugins)

    expect(setErrorStack).toHaveBeenCalledWith(error, 'Custom stack trace')
    expect(setErrorMessage).toHaveBeenCalledWith(error, 'Custom error message')
    expect(setErrorProps).not.toHaveBeenCalled()
  })

  it('should set error properties when newProps are provided', () => {
    const newProps = {
      code: 'ERR_CUSTOM',
      status: 500,
      details: { userId: 123 }
    }

    assignError(error, newProps, plugins)

    expect(setErrorProps).toHaveBeenCalledWith(error, ['code', 'status', 'details'])
    expect(excludeKeys).toHaveBeenCalledWith(
      newProps,
      [...OMITTED_PROPS, 'method1', 'method2']
    )
    expect(setErrorStack).not.toHaveBeenCalled()
    expect(setErrorMessage).not.toHaveBeenCalled()
  })

  it('should handle both error properties and stack/message', () => {
    const newProps = {
      stack: 'Custom stack',
      message: 'Custom message',
      code: 'ERR_CUSTOM',
      status: 500
    }

    assignError(error, newProps, plugins)

    expect(setErrorStack).toHaveBeenCalledWith(error, 'Custom stack')
    expect(setErrorMessage).toHaveBeenCalledWith(error, 'Custom message')
    expect(setErrorProps).toHaveBeenCalledWith(error, ['code', 'status'])
  })

  it('should not set error properties when newProps has no keys after excluding', () => {
    const newProps = { message: 'Custom message' }
    excludeKeys.mockReturnValue([])

    assignError(error, newProps, plugins)

    expect(setErrorProps).not.toHaveBeenCalled()
    expect(setErrorMessage).toHaveBeenCalledWith(error, 'Custom message')
  })

  it('should not call setErrorProps when newProps has no additional properties', () => {
    const newProps = { message: 'Custom message' }

    assignError(error, newProps, plugins)

    expect(setErrorProps).not.toHaveBeenCalled()
  })

  it('should not call setErrorProps when newProps only contains stack and message', () => {
    const newProps = {
      stack: 'Custom stack',
      message: 'Custom message'
    }

    assignError(error, newProps, plugins)

    expect(setErrorProps).not.toHaveBeenCalled()
  })

  it('should handle empty plugins array', () => {
    const newProps = { code: 'ERR_CUSTOM' }
    getPluginsMethodNames.mockReturnValue([])

    assignError(error, newProps, [])

    expect(setErrorProps).toHaveBeenCalledWith(error, ['code'])
    expect(excludeKeys).toHaveBeenCalledWith(
      newProps,
      [...OMITTED_PROPS]
    )
  })

  it('should handle undefined plugins', () => {
    const newProps = { code: 'ERR_CUSTOM' }

    assignError(error, newProps, undefined)

    expect(setErrorProps).toHaveBeenCalledWith(error, ['code'])
    expect(excludeKeys).toHaveBeenCalledWith(
      newProps,
      [...OMITTED_PROPS]
    )
  })

  it('should handle properties that need to be excluded', () => {
    const newProps = {
      code: 'ERR_CUSTOM',
      __proto__: {},
      constructor: {},
      prototype: {}
    }

    assignError(error, newProps, plugins)

    expect(setErrorProps).toHaveBeenCalledWith(error, ['code'])
    expect(excludeKeys).toHaveBeenCalledWith(
      newProps,
      [...OMITTED_PROPS, 'method1', 'method2']
    )
  })

  it('should handle Symbol properties in newProps', () => {
    const sym = Symbol('test')
    const newProps = {
      [sym]: 'symbol value',
      message: 'Custom message'
    }

    assignError(error, newProps, plugins)

    expect(setErrorProps).toHaveBeenCalledWith(error, [sym])
    expect(setErrorMessage).toHaveBeenCalledWith(error, 'Custom message')
  })

  it('should not modify error when no properties are provided', () => {
    const newProps = {}

    assignError(error, newProps, plugins)

    expect(setErrorStack).not.toHaveBeenCalled()
    expect(setErrorMessage).not.toHaveBeenCalled()
    expect(setErrorProps).not.toHaveBeenCalled()
  })

  it('should handle null error object', () => {
    const newProps = { message: 'Custom message' }

    assignError(null, newProps, plugins)

    expect(setErrorMessage).toHaveBeenCalledWith(null, 'Custom message')
  })
})

