const isPlainObj = (obj) => {
  return obj !== null && typeof obj === 'object' && Object.getPrototypeOf(obj) === Object.prototype;
};

// Mock validateMethod
const validateMethod = jest.fn();

describe('normalizeMethods', () => {
  const mockPlugin = {
    fullName: 'test-plugin',
    otherProp: 'value'
  };

  const mockCoreObject = {};
  const mockCoreObjectName = 'TestCore';
  const mockForbiddenNames = ['reservedMethod'];

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('successful normalization', () => {
    it('should return plugin with methods when propName exists and is plain object', () => {
      const propName = 'testMethods';
      const methods = {
        method1: () => {},
        method2: function() {}
      };

      const pluginWithMethods = {
        ...mockPlugin,
        [propName]: methods
      };

      const result = normalizeMethods({
        plugin: pluginWithMethods,
        propName,
        coreObject: mockCoreObject,
        coreObjectName: mockCoreObjectName,
        forbiddenNames: mockForbiddenNames
      });

      expect(result).toEqual(pluginWithMethods);
      expect(validateMethod).toHaveBeenCalledTimes(2);
      expect(validateMethod).toHaveBeenCalledWith({
        methodValue: methods.method1,
        propName,
        methodName: 'method1',
        plugin: pluginWithMethods,
        coreObject: mockCoreObject,
        coreObjectName: mockCoreObjectName,
        forbiddenNames: mockForbiddenNames
      });
      expect(validateMethod).toHaveBeenCalledWith({
        methodValue: methods.method2,
        propName,
        methodName: 'method2',
        plugin: pluginWithMethods,
        coreObject: mockCoreObject,
        coreObjectName: mockCoreObjectName,
        forbiddenNames: mockForbiddenNames
      });
    });

    it('should return plugin with empty methods object when propName is undefined', () => {
      const propName = 'undefinedMethods';
      const result = normalizeMethods({
        plugin: mockPlugin,
        propName,
        coreObject: mockCoreObject,
        coreObjectName: mockCoreObjectName,
        forbiddenNames: mockForbiddenNames
      });

      expect(result).toEqual({
        ...mockPlugin,
        [propName]: {}
      });
      expect(validateMethod).not.toHaveBeenCalled();
    });

    it('should return plugin with empty methods object when propName is null', () => {
      const propName = 'nullMethods';
      const pluginWithNull = {
        ...mockPlugin,
        [propName]: null
      };

      const result = normalizeMethods({
        plugin: pluginWithNull,
        propName,
        coreObject: mockCoreObject,
        coreObjectName: mockCoreObjectName,
        forbiddenNames: mockForbiddenNames
      });

      expect(result).toEqual({
        ...mockPlugin,
        [propName]: {}
      });
      expect(validateMethod).not.toHaveBeenCalled();
    });
  });

  describe('error cases', () => {
    it('should throw TypeError when propName value is not a plain object', () => {
      const propName = 'invalidMethods';
      const nonObjectMethods = 'not an object';

      const pluginWithNonObject = {
        ...mockPlugin,
        [propName]: nonObjectMethods
      };

      expect(() => {
        normalizeMethods({
          plugin: pluginWithNonObject,
          propName,
          coreObject: mockCoreObject,
          coreObjectName: mockCoreObjectName,
          forbiddenNames: mockForbiddenNames
        });
      }).toThrow(TypeError);

      expect(() => {
        normalizeMethods({
          plugin: pluginWithNonObject,
          propName,
          coreObject: mockCoreObject,
          coreObjectName: mockCoreObjectName,
          forbiddenNames: mockForbiddenNames
        });
      }).toThrow(
        `The plugin "${mockPlugin.fullName}"'s "${propName}" property must be either undefined or a plain object, not: ${nonObjectMethods}`
      );
      expect(validateMethod).not.toHaveBeenCalled();
    });

    it('should throw TypeError when propName value is an array', () => {
      const propName = 'arrayMethods';
      const arrayMethods = [() => {}, function() {}];

      const pluginWithArray = {
        ...mockPlugin,
        [propName]: arrayMethods
      };

      expect(() => {
        normalizeMethods({
          plugin: pluginWithArray,
          propName,
          coreObject: mockCoreObject,
          coreObjectName: mockCoreObjectName,
          forbiddenNames: mockForbiddenNames
        });
      }).toThrow(TypeError);

      expect(() => {
        normalizeMethods({
          plugin: pluginWithArray,
          propName,
          coreObject: mockCoreObject,
          coreObjectName: mockCoreObjectName,
          forbiddenNames: mockForbiddenNames
        });
      }).toThrow(
        `The plugin "${mockPlugin.fullName}"'s "${propName}" property must be either undefined or a plain object, not: ${arrayMethods}`
      );
      expect(validateMethod).not.toHaveBeenCalled();
    });

    it('should throw TypeError when propName value is a function', () => {
      const propName = 'functionMethods';
      const functionMethods = () => {};

      const pluginWithFunction = {
        ...mockPlugin,
        [propName]: functionMethods
      };

      expect(() => {
        normalizeMethods({
          plugin: pluginWithFunction,
          propName,
          coreObject: mockCoreObject,
          coreObjectName: mockCoreObjectName,
          forbiddenNames: mockForbiddenNames
        });
      }).toThrow(TypeError);

      expect(() => {
        normalizeMethods({
          plugin: pluginWithFunction,
          propName,
          coreObject: mockCoreObject,
          coreObjectName: mockCoreObjectName,
          forbiddenNames: mockForbiddenNames
        });
      }).toThrow(
        `The plugin "${mockPlugin.fullName}"'s "${propName}" property must be either undefined or a plain object, not: ${functionMethods}`
      );
      expect(validateMethod).not.toHaveBeenCalled();
    });
  });

  describe('edge cases', () => {
    it('should handle empty methods object', () => {
      const propName = 'emptyMethods';
      const emptyMethods = {};

      const pluginWithEmpty = {
        ...mockPlugin,
        [propName]: emptyMethods
      };

      const result = normalizeMethods({
        plugin: pluginWithEmpty,
        propName,
        coreObject: mockCoreObject,
        coreObjectName: mockCoreObjectName,
        forbiddenNames: mockForbiddenNames
      });

      expect(result).toEqual(pluginWithEmpty);
      expect(validateMethod).not.toHaveBeenCalled();
    });

    it('should preserve other plugin properties', () => {
      const propName = 'testMethods';
      const methods = { testMethod: () => {} };

      const pluginWithExtraProps = {
        ...mockPlugin,
        extraProp1: 'value1',
        extraProp2: 42,
        [propName]: methods
      };

      const result = normalizeMethods({
        plugin: pluginWithExtraProps,
        propName,
        coreObject: mockCoreObject,
        coreObjectName: mockCoreObjectName,
        forbiddenNames: mockForbiddenNames
