      expect(result).toEqual(pluginWithExtraProps);
      expect(result.extraProp1).toBe('value1');
      expect(result.extraProp2).toBe(42);
      expect(validateMethod).toHaveBeenCalledTimes(1);
    });

    it('should call validateMethod for each method in the object', () => {
      const propName = 'multipleMethods';
      const methods = {
        methodA: () => {},
        methodB: function() {},
        methodC: () => {}
      };

      const pluginWithMultiple = {
        ...mockPlugin,
        [propName]: methods
      };

      normalizeMethods({
        plugin: pluginWithMultiple,
        propName,
