        methodName: 'methodA',
        methodValue: methods.methodA
      }));
      expect(validateMethod).toHaveBeenCalledWith(expect.objectContaining({
        methodName: 'methodB',
        methodValue: methods.methodB
      }));
      expect(validateMethod).toHaveBeenCalledWith(expect.objectContaining({
        methodName: 'methodC',
        methodValue: methods.methodC
      }));
    });
  });
});

