jest.mock('../../../../src/plugins/shape/normalizeGetOptions.js', () => 
  jest.fn(({ plugin }) => ({ ...plugin, getOptionsNormalized: true })))

// Import mocked functions
const validatePluginName = require('../../../../src/plugins/shape/validatePluginName.js')
const validateOptionalFuncs = require('../../../../src/plugins/shape/validateOptionalFuncs.js')
const normalizeAllMethods = require('../../../../src/plugins/shape/normalizeAllMethods.js')
const validateSameMethods = require('../../../../src/plugins/shape/validateSameMethods.js')
const normalizeIsOptions = require('../../../../src/plugins/shape/normalizeIsOptions.js')
const normalizeGetOptions = require('../../../../src/plugins/shape/normalizeGetOptions.js')

// Mock the normalizePlugin function
jest.mock('../../../../src/plugins/shape/main.js', () => {
  // Create a mock implementation that includes isPlainObj logic
  const mockNormalizePlugin = jest.fn((plugin, ParentError) => {
    // Simple isPlainObj implementation for testing
    const isPlainObj = (obj) => {
      return obj !== null && 
             typeof obj === 'object' && 
             !Array.isArray(obj) && 
             !(obj instanceof Function) &&
             Object.getPrototypeOf(obj) === Object.prototype
    }

    if (!isPlainObj(plugin)) {
      throw new TypeError(
        `The "plugins" option of "${ParentError.name}.subclass()" must be an array of plugin objects: ${plugin}`,
      )
    }

    const pluginA = validatePluginName(plugin)
    validateOptionalFuncs(pluginA)
    const pluginB = normalizeAllMethods(pluginA)
    validateSameMethods(pluginB)
    const pluginC = normalizeIsOptions({ plugin: pluginB })
    const pluginD = normalizeGetOptions({ plugin: pluginC })
    return pluginD
  })

  return { normalizePlugin: mockNormalizePlugin }
})

describe('normalizePlugin', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  describe('input validation', () => {
    it('should throw TypeError when plugin is not a plain object', () => {
      const ParentError = { name: 'TestError' }

      expect(() => normalizePlugin(null, ParentError)).toThrow(TypeError)
      expect(() => normalizePlugin(undefined, ParentError)).toThrow(TypeError)
      expect(() => normalizePlugin(123, ParentError)).toThrow(TypeError)
      expect(() => normalizePlugin('string', ParentError)).toThrow(TypeError)
      expect(() => normalizePlugin([], ParentError)).toThrow(TypeError)
      expect(() => normalizePlugin(() => {}, ParentError)).toThrow(TypeError)

      const errorMessage = `The "plugins" option of "${ParentError.name}.subclass()" must be an array of plugin objects:`
      expect(() => normalizePlugin(null, ParentError)).toThrow(errorMessage)
    })

    it('should not throw when plugin is a plain object', () => {
      const ParentError = { name: 'TestError' }
      const plugin = { name: 'testPlugin' }

      expect(() => normalizePlugin(plugin, ParentError)).not.toThrow()
    })

    it('should not throw when plugin is an empty object', () => {
      const ParentError = { name: 'TestError' }
      const plugin = {}

      expect(() => normalizePlugin(plugin, ParentError)).not.toThrow()
    })
  })

  describe('plugin normalization flow', () => {
    it('should call all normalization functions in correct order', () => {
      const ParentError = { name: 'TestError' }
      const plugin = { name: 'testPlugin', someMethod: () => {} }

      const result = normalizePlugin(plugin, ParentError)

      // Verify call order and arguments
      expect(validatePluginName).toHaveBeenCalledWith(plugin)
      expect(validateOptionalFuncs).toHaveBeenCalledWith({ ...plugin, nameValidated: true })
      expect(normalizeAllMethods).toHaveBeenCalledWith({ ...plugin, nameValidated: true })
      expect(validateSameMethods).toHaveBeenCalledWith({ ...plugin, nameValidated: true, methodsNormalized: true })
      expect(normalizeIsOptions).toHaveBeenCalledWith({ 
        plugin: { ...plugin, nameValidated: true, methodsNormalized: true } 
      })
      expect(normalizeGetOptions).toHaveBeenCalledWith({ 
        plugin: { ...plugin, nameValidated: true, methodsNormalized: true, isOptionsNormalized: true } 
      })

      // Verify final result contains all normalization flags
      expect(result).toEqual({
        ...plugin,
        nameValidated: true,
        methodsNormalized: true,
        isOptionsNormalized: true,
        getOptionsNormalized: true
      })
    })

    it('should preserve all original plugin properties', () => {
      const ParentError = { name: 'TestError' }
      const plugin = {
        name: 'testPlugin',
        method1: () => 'result1',
        method2: () => 'result2',
        config: { option1: 'value1' }
      }

      const result = normalizePlugin(plugin, ParentError)

      expect(result.name).toBe('testPlugin')
      expect(result.method1).toBe(plugin.method1)
      expect(result.method2).toBe(plugin.method2)
      expect(result.config).toEqual(plugin.config)
    })
  })

  describe('ParentError parameter', () => {
    it('should include ParentError.name in error message', () => {
      const ParentError = { name: 'CustomError' }
      const errorMessage = `The "plugins" option of "${ParentError.name}.subclass()" must be an array of plugin objects:`

      expect(() => normalizePlugin(null, ParentError)).toThrow(errorMessage)
    })

    it('should work with different ParentError names', () => {
      const ParentError1 = { name: 'ErrorType1' }
      const ParentError2 = { name: 'ErrorType2' }

      expect(() => normalizePlugin(null, ParentError1)).toThrow('ErrorType1')
      expect(() => normalizePlugin(null, ParentError2)).toThrow('ErrorType2')
    })
  })

  describe('edge cases', () => {
    it('should handle empty plugin object', () => {
      const ParentError = { name: 'TestError' }
      const plugin = {}

      const result = normalizePlugin(plugin, ParentError)

      expect(result).toEqual({
        nameValidated: true,
        methodsNormalized: true,
        isOptionsNormalized: true,
        getOptionsNormalized: true
      })
    })

    it('should handle plugin with only name property', () => {
      const ParentError = { name: 'TestError' }
      const plugin = { name: 'simplePlugin' }

      const result = normalizePlugin(plugin, ParentError)

      expect(result.name).toBe('simplePlugin')
      expect(result.nameValidated).toBe(true)
    })

    it('should handle plugin with nested objects', () => {
      const ParentError = { name: 'TestError' }
      const plugin = {
        name: 'complexPlugin',
        options: {
          nested: {
            deep: 'value'
          }
        },
        methods: {
          method1: () => {},
          method2: () => {}
        }
      }

      const result = normalizePlugin(plugin, ParentError)

      expect(result.name).toBe('complexPlugin')
      expect(result.options).toEqual(plugin.options)
      expect(result.methods).toEqual(plugin.methods)
    })
  })

  describe('function composition', () => {
    it('should pass results from one function to the next', () => {
      const ParentError = { name: 'TestError' }
      const plugin = { name: 'test' }

      // Setup mocks to add specific properties
      validatePluginName.mockImplementationOnce((p) => ({ ...p, step1: true }))
      normalizeAllMethods.mockImplementationOnce((p) => ({ ...p, step2: true }))
      normalizeIsOptions.mockImplementationOnce(({ plugin: p }) => ({ ...p, step3: true }))
      normalizeGetOptions.mockImplementationOnce(({ plugin: p }) => ({ ...p, step4: true }))

      const result = normalizePlugin(plugin, ParentError)

      // Verify each step receives the output from previous step
      expect(validatePluginName).toHaveBeenCalledWith(plugin)
      expect(normalizeAllMethods).toHaveBeenCalledWith(expect.objectContaining({ step1: true }))
      expect(normalizeIsOptions).toHaveBeenCalledWith({ 
        plugin: expect.objectContaining({ step1: true, step2: true }) 
      })
      expect(normalizeGetOptions).toHaveBeenCalledWith({ 
        plugin: expect.objectContaining({ step1: true, step2: true, step3: true }) 
      })

      expect(result).toEqual(expect.objectContaining({
        name: 'test',
        step1: true,
        step2: true,
        step3: true,
        step4: true
      }))
    })
  })
})

